CREATE TYPE "MovementType" AS ENUM ('OPENING', 'RECEIPT', 'CORRECTION', 'DAMAGE', 'MISSING', 'RETURN', 'OTHER');
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL UNIQUE, "archived" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Supplier" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "contactPerson" TEXT, "phone" TEXT, "city" TEXT, "notes" TEXT, "archived" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "brand" TEXT, "description" TEXT, "imageUrl" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "categoryId" TEXT NOT NULL, "supplierId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "Product_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Variant" ("id" TEXT PRIMARY KEY, "productId" TEXT NOT NULL, "sku" TEXT NOT NULL UNIQUE, "size" TEXT, "colour" TEXT, "quantity" INTEGER NOT NULL DEFAULT 0 CHECK ("quantity" >= 0), "purchasePaise" INTEGER CHECK ("purchasePaise" >= 0), "sellingPaise" INTEGER CHECK ("sellingPaise" >= 0), "reorderAt" INTEGER NOT NULL DEFAULT 2 CHECK ("reorderAt" >= 0), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Variant_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "StockBatch" ("id" TEXT PRIMARY KEY, "variantId" TEXT NOT NULL, "receivedQty" INTEGER NOT NULL CHECK ("receivedQty" > 0), "remainingQty" INTEGER NOT NULL CHECK ("remainingQty" >= 0), "unitCostPaise" INTEGER CHECK ("unitCostPaise" >= 0), "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockBatch_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "Variant"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "InventoryMovement" ("id" TEXT PRIMARY KEY, "variantId" TEXT NOT NULL, "type" "MovementType" NOT NULL, "delta" INTEGER NOT NULL, "beforeQty" INTEGER NOT NULL CHECK ("beforeQty" >= 0), "afterQty" INTEGER NOT NULL CHECK ("afterQty" >= 0), "reason" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InventoryMovement_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "Variant"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Supplier_name_idx" ON "Supplier"("name");
CREATE INDEX "Product_name_idx" ON "Product"("name");
CREATE INDEX "Product_createdAt_idx" ON "Product"("createdAt");
CREATE INDEX "Variant_productId_idx" ON "Variant"("productId");
CREATE INDEX "Variant_quantity_reorderAt_idx" ON "Variant"("quantity", "reorderAt");
CREATE INDEX "StockBatch_variantId_receivedAt_idx" ON "StockBatch"("variantId", "receivedAt");
CREATE INDEX "InventoryMovement_variantId_createdAt_idx" ON "InventoryMovement"("variantId", "createdAt");
CREATE INDEX "InventoryMovement_createdAt_idx" ON "InventoryMovement"("createdAt");
